draw:
var pad = 36;
var R = 8.31;
var n = 1.0, T = p.temp, Vi = 1.0;
var Vf = p.vf;

var Vax = 6.4;
var Pi = n * R * T / (Vi * 1e-3) / 1e5;
var Pax = Math.max(Pi * 1.25, 1);

var X = function(v){ return pad + v / Vax * (W - pad - 16); };
var Y = function(q){ return H - pad - q / Pax * (H - pad - 26); };

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(Vax), Y(0));
ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(0), Y(Pax));
ctx.stroke();
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle = C.ink;
ctx.fillText("V (litres)", X(Vax) - 56, Y(0) + 16);
ctx.fillText("P (bar)", X(0) + 4, Y(Pax) + 8);

var Pof = function(v){ return n * R * T / (v * 1e-3) / 1e5; };

// shaded area under the isotherm from Vi to Vf
ctx.fillStyle = C.faint;
ctx.globalAlpha = 0.4;
ctx.beginPath();
ctx.moveTo(X(Vi), Y(0));
for (var v = Vi; v <= Vf + 1e-9; v += (Vf - Vi) / 80) { ctx.lineTo(X(v), Y(Pof(v))); }
ctx.lineTo(X(Vf), Y(0));
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// the isotherm itself
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
var first = true;
for (var v2 = 0.5; v2 <= Vax; v2 += 0.04) {
  var q = Pof(v2);
  if (q > Pax) { first = true; continue; }
  if (first) { ctx.moveTo(X(v2), Y(q)); first = false; } else { ctx.lineTo(X(v2), Y(q)); }
}
ctx.stroke();

// the isobar at the same start pressure, for comparison
ctx.strokeStyle = C.ink;
ctx.setLineDash([5, 4]);
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(X(Vi), Y(Pi)); ctx.lineTo(X(Vf), Y(Pi)); ctx.stroke();
ctx.setLineDash([]);

// end points
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(Vi), Y(Pi), 4, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(Vf), Y(Pof(Vf)), 4, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("start", X(Vi) - 6, Y(Pi) - 8);
ctx.fillText("end", X(Vf) + 6, Y(Pof(Vf)) - 6);
ctx.fillStyle = C.faint;
ctx.fillText("isobar at the same start pressure", X(Vi) + 8, Y(Pi) + 16);

var Wiso = n * R * T * Math.log(Vf / Vi);
var Wbar = Pi * 1e5 * (Vf - Vi) * 1e-3;

out.note = "isothermal work (shaded) = nRT ln(Vf/Vi) = " + Wiso.toFixed(0) + " J. Along the dashed isobar the same volume change would give P dV = " + Wbar.toFixed(0) + " J.";
